  ('R-6', 'other', 6, 'Everything anyone changed', 'The audit log as a report: discounts approved, prices changed, sales voided, limits overridden, stock written off. BMS calls it the Modification Register.', 'audit', array['d', 'action'], '[{"f":"d","l":"Date","t":"date"},{"f":"at","l":"Time","t":"text"},{"f":"action","l":"What","t":"text"},{"f":"who","l":"Who","t":"text"},{"f":"branch","l":"Branch","t":"text"},{"f":"entity","l":"On","t":"text"},{"f":"details","l":"Details","t":"text"}]'::jsonb, null, null, 'range', false, null, false, null, null, null),
  ('R-7', 'other', 7, 'Warranty claims', 'Every claim with how long it has been open. BMS calls it the RMA Service Register.', 'claims', array['status', 'claim_no'], '[{"f":"status","l":"Status","t":"text"},{"f":"claim_no","l":"Claim No","t":"text"},{"f":"d","l":"Taken in","t":"date"},{"f":"trader","l":"Customer","t":"text"},{"f":"product","l":"Product","t":"text"},{"f":"serial","l":"Serial","t":"text"},{"f":"fault","l":"Fault","t":"text"},{"f":"technician","l":"With","t":"text"},{"f":"days_open","l":"Days","t":"num","calc":"average"}]'::jsonb, null, null, 'range', false, null, false, null, null, null),
