  ('R-11', 'other', 11, 'Attendance', 'Day by day, per person. How it was recorded is a column: somebody checking in at the branch and a manager''s word are not the same kind of evidence.', 'attendance', array['employee', 'd'], '[{"f":"employee","l":"Employee","t":"text"},{"f":"designation","l":"Designation","t":"text"},{"f":"d","l":"Date","t":"date"},{"f":"status","l":"Status","t":"text"},{"f":"in_at","l":"In","t":"text"},{"f":"out_at","l":"Out","t":"text"},{"f":"minutes_late","l":"Minutes late","t":"num","calc":"average"},{"f":"recorded","l":"How","t":"text"},{"f":"days_worked","l":"Days worked","t":"qty"},{"f":"days_absent","l":"Absent","t":"qty"},{"f":"days_leave","l":"On leave","t":"qty"}]'::jsonb, null, null, 'range', false, null, true, null, null, null),
  ('R-12', 'other', 12, 'Salary sheet', 'What each person was paid and what came off it. Every deduction is shown, because a deduction nobody can explain is an argument every month.', 'salary', array['month', 'employee'], '[{"f":"month","l":"Month","t":"text"},{"f":"employee","l":"Employee","t":"text"},{"f":"designation","l":"Designation","t":"text"},{"f":"basic","l":"Basic","t":"money"},{"f":"allowances","l":"Allowances","t":"money"},{"f":"days_worked","l":"Days worked","t":"qty"},{"f":"absent_days","l":"Days absent","t":"qty"},{"f":"absence_cut","l":"Less absence","t":"money"},{"f":"advance_cut","l":"Less advance","t":"money"},{"f":"net","l":"Net paid","t":"money"},{"f":"sheet_status","l":"Status","t":"text"}]'::jsonb, null, null, 'range', true, null, true, null, null, null),
